// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    address authorized = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { c = new EBU(); }

    function testFuzz_property(uint256 amount, uint8 count) public {
        // keep params in the admissible domain (wide)
        amount = bound(amount, 1, 1e18);
        count = uint8(bound(count, 1, 5));

        address[] memory tos = new address[](count);
        uint[] memory vs = new uint[](count);
        for (uint i = 0; i < count; i++) {
            tos[i] = address(uint160(0x1000 + i));
            vs[i] = amount;
        }

        vm.prank(authorized);
        bool ok = c.transfer(tos, vs);

        // rule: any transfer that completes must report success (return true)
        assertTrue(ok);
    }
}
